def net_tape(orders):
    rest = []
    for q in orders:
        if q > 0:
            rest.append(q)
            continue
        need = -q
        while need and rest and rest[-1] > 0:
            take = min(need, rest[-1])
            need -= take
            rest[-1] -= take
            if rest[-1] == 0:
                rest.pop()
        if need:
            rest.append(-need)
    return rest

