def net_tape(orders):
    rest = []
    for q in orders:
        if q > 0:
            rest.append(q)
            continue
        need = -q
        while need and rest and rest[-1] > 0:
            take = min(need, rest[-1])
            need -= take
            if take == rest[-1]:
                rest = rest[:-1]
            else:
                rest = rest[:-1] + [rest[-1] - take]
        if need:
            rest.append(-need)
    return rest
